<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import type { ClassificationPublication } from './classification-workbench'
interface Target {id:number;name:string;endpoint:string;enabled:boolean;revision:number;createdAt:string;hasToken:boolean;autoEvents?:boolean;minSeverity?:string}
interface Delivery {id:number;publicationId?:number;resourceKind?:string;resourceId?:number;targetId:number;targetName:string;status:string;attempts:number;payloadDigest:string;remoteRef:string;errorCode:string;createdAt:string;deliveredAt?:string}
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>();const base=workspacePath(props.workspace.slug)+'/classification',owner=computed(()=>props.workspace.role==='owner'),editor=computed(()=>['owner','operator'].includes(props.workspace.role))
const targets=ref<Target[]>([]),publications=ref<ClassificationPublication[]>([]),deliveries=ref<Delivery[]>([]),targetId=ref(''),publicationId=ref(''),editing=ref<Target>(),form=reactive({name:'',endpoint:'',enabled:true,autoEvents:false,minSeverity:'high'}),showForm=ref(false),token=ref(''),showToken=ref(false),busy=ref(false),error=ref(''),notice=ref('');const active=new AbortController();let sequence=0
const labels:Record<string,string>={queued:'已排队，等待客户侧执行器',delivering:'客户侧交付中',accepted:'接收方已确认接收',failed:'交付失败，可重试',cancelled:'已取消'}
function failed(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=describeError(e)}
async function load(){try{const [t,p]=await Promise.all([request<{items:Target[]}>(base+'/delivery-targets',{signal:active.signal}),request<{items:ClassificationPublication[]}>(base+'/publications',{signal:active.signal})]);targets.value=t.items;publications.value=p.items.filter(p=>p.status==='published');await loadDeliveries()}catch(e){failed(e)}}
async function loadDeliveries(){const seq=++sequence;error.value='';try{const q=new URLSearchParams();if(targetId.value)q.set('targetId',targetId.value);if(publicationId.value)q.set('publicationId',publicationId.value);const r=await request<{items:Delivery[]}>(base+'/deliveries?'+q,{signal:active.signal});if(seq===sequence)deliveries.value=r.items}catch(e){if(seq===sequence)failed(e)}}
function edit(target?:Target){editing.value=target;Object.assign(form,target?{name:target.name,endpoint:target.endpoint,enabled:target.enabled,autoEvents:!!target.autoEvents,minSeverity:target.minSeverity||'high'}:{name:'',endpoint:'',enabled:true,autoEvents:false,minSeverity:'high'});showForm.value=true;token.value='';showToken.value=false}
async function save(){if(!owner.value||busy.value)return;busy.value=true;error.value='';token.value='';showToken.value=false;try{const r=await request<{target?:Target;token?:string}&Partial<Target>>(base+'/delivery-targets'+(editing.value?'/'+editing.value.id:''),{method:editing.value?'PUT':'POST',body:JSON.stringify({...form,revision:editing.value?.revision||0}),signal:active.signal});token.value=r.token||'';showForm.value=false;await load();notice.value='交付目标已保存。配置客户侧执行器后，才会连接明确登记的接收地址。'}catch(e){failed(e)}finally{busy.value=false}}
async function rotate(target:Target){if(!owner.value||busy.value)return;busy.value=true;error.value='';token.value='';showToken.value=false;try{const r=await request<{token:string}>(base+'/delivery-targets/'+target.id+'/rotate',{method:'POST',body:JSON.stringify({revision:target.revision}),signal:active.signal});token.value=r.token;await load();notice.value='令牌已更换，原令牌不再可用。请更新客户侧执行器。'}catch(e){failed(e)}finally{busy.value=false}}
async function send(){if(!editor.value||!targetId.value||!publicationId.value||busy.value)return;busy.value=true;error.value='';try{await request(base+'/publications/'+publicationId.value+'/deliveries',{method:'POST',body:JSON.stringify({targetId:Number(targetId.value)}),signal:active.signal});await loadDeliveries();notice.value='已登记冻结分类快照交付任务。排队不代表接收方已接收，请核对后续回执。'}catch(e){failed(e)}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(token.value);notice.value='一次性令牌已复制，请仅配置于受控客户侧执行器。'}catch{notice.value='复制不可用，可临时显示后手动保存。'}}
onMounted(load);onBeforeUnmount(()=>{active.abort();token.value='';showToken.value=false})
</script>
<template><section class="delivery-panel"><div class="panel-heading"><div><h2>已发布分类交付</h2><p>将独立评审后的冻结分类快照交给已登记接收方，保留任务、摘要与真实接收回执。</p></div><button v-if="owner" class="button button-primary" @click="edit()">新增交付目标</button></div><p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<aside v-if="token" class="panel delivery-form"><h3>客户侧目标令牌 · 仅本次提供</h3><input :type="showToken?'text':'password'" :value="token" readonly aria-label="客户侧交付目标令牌"><p>仅配置到classification-delivery-agent，不放入浏览器扩展或第三方页面。离开本页后会清除。</p><div class="actions"><button class="button" @click="copy">复制令牌</button><button class="button" @click="showToken=!showToken">{{showToken?'隐藏':'临时显示'}}</button><button class="button" @click="token='';showToken=false">已安全保存</button></div></aside>
<form v-if="showForm" class="panel delivery-form" @submit.prevent="save"><h3>{{editing?'修订交付目标':'新增交付目标'}}</h3><label>目标名称<input v-model="form.name" maxlength="120" required></label><label>接收地址<input v-model="form.endpoint" type="url" maxlength="1000" placeholder="https://已授权接收方/分类接口" required></label><p>允许HTTPS或本地回环HTTP。客户侧执行器仍须显式配置相同接收地址，平台不直接探测任意内网地址。</p><label class="check"><input v-model="form.enabled" type="checkbox">启用此目标</label><label class="check"><input v-model="form.autoEvents" type="checkbox">按以下等级将新安全事件自动加入此目标交付队列</label><label>自动事件最低等级<select v-model="form.minSeverity"><option value="low">低</option><option value="medium">中</option><option value="high">高</option><option value="critical">严重</option></select></label><p>企业接收方可再接SOC、工单或通知渠道；平台只记录实际交付回执，不把排队视为邮件或消息送达。</p><div class="actions"><button class="button" type="button" @click="showForm=false">取消</button><button class="button button-primary" :disabled="busy">保存目标</button></div></form>
<section class="panel"><div class="panel-heading"><h3>已登记目标 · {{targets.length}}</h3><button class="button" :disabled="busy" @click="load">刷新</button></div><p v-if="!targets.length" class="message">尚未登记交付目标。需要由负责人配置接收地址和客户侧执行器。</p><div v-else class="table-wrap"><table><thead><tr><th>目标</th><th>地址</th><th>状态 / 修订</th><th>操作</th></tr></thead><tbody><tr v-for="target in targets" :key="target.id"><th scope="row">{{target.name}}</th><td>{{target.endpoint}}</td><td>{{target.enabled?'已启用':'已暂停'}} · v{{target.revision}}<small>{{target.autoEvents?'自动订阅安全事件 · '+target.minSeverity:'未启用自动事件订阅'}}</small></td><td><div v-if="owner" class="actions"><button class="button" :disabled="busy" @click="edit(target)">修订</button><button class="button" :disabled="busy" @click="rotate(target)">更换令牌</button></div></td></tr></tbody></table></div></section>
<section class="panel delivery-form"><h3>提交交付与核对回执</h3><div class="delivery-scope"><label>已发布分类快照<select v-model="publicationId" @change="loadDeliveries"><option value="">请选择已发布快照</option><option v-for="p in publications" :key="p.id" :value="String(p.id)">{{p.title}} · #{{p.id}} · {{p.itemCount}}项</option></select></label><label>已登记接收方<select v-model="targetId" @change="loadDeliveries"><option value="">请选择接收方</option><option v-for="t in targets" :key="t.id" :value="String(t.id)">{{t.name}}{{t.enabled?'':'（已暂停）'}}</option></select></label></div><button class="button button-primary" :disabled="!editor||busy||!publicationId||!targets.find(t=>String(t.id)===targetId)?.enabled" @click="send">提交交付 / 重试失败任务</button><p>相同快照与接收方幂等。接收回执仅证明接收方确认了相同摘要，不代表第三方标签已实际写入或已完成监管报送。</p><p v-if="!deliveries.length">当前筛选范围没有交付任务。</p><div v-else class="table-wrap"><table><thead><tr><th>任务 / 快照</th><th>接收方</th><th>实际状态</th><th>证据 / 回执</th><th>时间</th></tr></thead><tbody><tr v-for="d in deliveries" :key="d.id"><th scope="row">#{{d.id}}<small>{{d.resourceKind==='security_event'?'安全事件 #'+d.resourceId:'分类快照 #'+(d.publicationId||d.resourceId)}}</small></th><td>{{d.targetName}}</td><td>{{labels[d.status]||d.status}}<small>尝试{{d.attempts}}次{{d.errorCode?' · '+d.errorCode:''}}</small></td><td><small>摘要 {{d.payloadDigest}}</small><span>{{d.remoteRef||'尚无接收方引用'}}</span></td><td>{{formatDate(d.createdAt)}}<small v-if="d.deliveredAt">回执 {{formatDate(d.deliveredAt)}}</small></td></tr></tbody></table></div></section></section></template>
<style scoped>.delivery-panel{display:grid;gap:18px;min-width:0}.delivery-panel>.panel-heading{padding:0}.delivery-panel h2{font-size:18px}.delivery-panel h3{font-size:15px}.delivery-panel p{font-size:12px;color:var(--secondary);line-height:1.85}.delivery-form{padding:20px;display:grid;gap:15px}.delivery-form label{display:grid;gap:7px;font-size:12px}.delivery-form input:not([type=checkbox]),.delivery-form select{font:inherit;border:1px solid var(--input-line);border-radius:6px;padding:9px 10px;background:var(--surface);color:var(--ink);min-width:0;max-width:100%}.delivery-form .check{display:flex;align-items:center;gap:8px}.delivery-form>.button{justify-self:start}.delivery-scope{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.delivery-panel table{width:100%;min-width:700px;border-collapse:collapse}.delivery-panel th,.delivery-panel td{font-size:12px;padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.delivery-panel small{display:block;font-size:11px;font-weight:400;color:var(--secondary);margin-top:5px}.actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}@media(max-width:800px){.delivery-scope{grid-template-columns:1fr}}</style>
